{
  "root": "main_stack",
  "state": {
    "current_allocation_data": [
      {
        "asset": "US Large Cap (VTI)",
        "current_value": "$62,500",
        "current_percentage": "62.5%",
        "target_percentage": "50%",
        "target_value": "$50,000"
      },
      {
        "asset": "International Stocks (VXUS)",
        "current_value": "$18,400",
        "current_percentage": "18.4%",
        "target_percentage": "25%",
        "target_value": "$25,000"
      },
      {
        "asset": "Total Bond Market (BND)",
        "current_value": "$12,100",
        "current_percentage": "12.1%",
        "target_percentage": "20%",
        "target_value": "$20,000"
      },
      {
        "asset": "Cash (Savings)",
        "current_value": "$7,000",
        "current_percentage": "7.0%",
        "target_percentage": "5%",
        "target_value": "$5,000"
      }
    ],
    "rebalancing_trades_data": [
      {
        "asset_class": "VTI (US Large Cap)",
        "current_percentage": "62.5%",
        "target_value": "$50,000",
        "required_action": "Sell $12,500"
      },
      {
        "asset_class": "VXUS (Intl Stocks)",
        "current_percentage": "18.4%",
        "target_value": "$25,000",
        "required_action": "Buy $6,600"
      },
      {
        "asset_class": "BND (Bond Market)",
        "current_percentage": "12.1%",
        "target_value": "$20,000",
        "required_action": "Buy $7,900"
      },
      {
        "asset_class": "Cash (Savings)",
        "current_percentage": "7.0%",
        "target_value": "$5,000",
        "required_action": "Sell $2,000"
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md",
        "padding": 16
      },
      "children": [
        "title_h1",
        "current_allocation_card",
        "rebalancing_trades_card",
        "diversification_impact_card",
        "quick_actions_card",
        "sources_card"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "December 2023 Portfolio Rebalancing",
        "variant": "h1"
      },
      "children": []
    },
    "current_allocation_card": {
      "type": "Card",
      "props": {},
      "children": [
        "current_allocation_image",
        "current_allocation_h2",
        "current_allocation_table"
      ]
    },
    "current_allocation_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/d/d1/Share_of_Stock_Market.png/1200px-Share_of_Stock_Market.png",
        "fit": "contain"
      },
      "children": []
    },
    "current_allocation_h2": {
      "type": "Text",
      "props": {
        "text": "Current Allocation vs Target Weights",
        "variant": "h2"
      },
      "children": []
    },
    "current_allocation_table": {
      "type": "Table",
      "props": {
        "statePath": "/current_allocation_data",
        "columns": [
          {
            "key": "asset",
            "label": "Asset"
          },
          {
            "key": "current_value",
            "label": "Current Value"
          },
          {
            "key": "current_percentage",
            "label": "Current %"
          },
          {
            "key": "target_percentage",
            "label": "Target %"
          },
          {
            "key": "target_value",
            "label": "Target Value"
          }
        ],
        "domain": "comparison",
        "preferredPresentation": "cards",
        "primaryColumn": "asset",
        "highlightColumns": [
          "current_percentage",
          "target_percentage"
        ]
      },
      "children": []
    },
    "rebalancing_trades_card": {
      "type": "Card",
      "props": {},
      "children": [
        "rebalancing_trades_image",
        "rebalancing_trades_h2",
        "rebalancing_trades_table"
      ]
    },
    "rebalancing_trades_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/e/e4/Financial_balance.jpg/1200px-Financial_balance.jpg",
        "fit": "contain"
      },
      "children": []
    },
    "rebalancing_trades_h2": {
      "type": "Text",
      "props": {
        "text": "Required Rebalancing Trades",
        "variant": "h2"
      },
      "children": []
    },
    "rebalancing_trades_table": {
      "type": "Table",
      "props": {
        "statePath": "/rebalancing_trades_data",
        "columns": [
          {
            "key": "asset_class",
            "label": "Asset Class"
          },
          {
            "key": "current_percentage",
            "label": "Current %"
          },
          {
            "key": "target_value",
            "label": "Target Value"
          },
          {
            "key": "required_action",
            "label": "Required Action"
          }
        ],
        "domain": "comparison",
        "preferredPresentation": "cards",
        "primaryColumn": "asset_class",
        "highlightColumns": [
          "required_action"
        ]
      },
      "children": []
    },
    "diversification_impact_card": {
      "type": "Card",
      "props": {},
      "children": [
        "diversification_impact_h3",
        "diversification_impact_text"
      ]
    },
    "diversification_impact_h3": {
      "type": "Text",
      "props": {
        "text": "Diversification Impact",
        "variant": "h3"
      },
      "children": []
    },
    "diversification_impact_text": {
      "type": "Text",
      "props": {
        "text": "The rebalancing process reduces the overweight position in US equities, which have outperformed recently, and redeploys capital into undervalued international stocks and bonds. This shift lowers the portfolio's overall volatility and aligns it with your long-term risk profile.",
        "variant": "body"
      },
      "children": []
    },
    "quick_actions_card": {
      "type": "Card",
      "props": {},
      "children": [
        "quick_actions_h3",
        "quick_actions_buttons_stack"
      ]
    },
    "quick_actions_h3": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "quick_actions_buttons_stack": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "md",
        "justify": "start",
        "wrap": "wrap"
      },
      "children": [
        "execute_trades_button",
        "view_dashboard_button"
      ]
    },
    "execute_trades_button": {
      "type": "Button",
      "props": {
        "label": "Execute Trades",
        "variant": "primary"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.vanguard.com"
          }
        }
      },
      "children": []
    },
    "view_dashboard_button": {
      "type": "Button",
      "props": {
        "label": "View Dashboard",
        "variant": "primary"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.schwab.com"
          }
        }
      },
      "children": []
    },
    "sources_card": {
      "type": "Card",
      "props": {},
      "children": [
        "sources_h3",
        "sources_links_stack"
      ]
    },
    "sources_h3": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h3"
      },
      "children": []
    },
    "sources_links_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "rebalancing_theory_button",
        "asset_allocation_button"
      ]
    },
    "rebalancing_theory_button": {
      "type": "Button",
      "props": {
        "label": "Rebalancing Theory",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.investopedia.com/terms/r/rebalancing.asp"
          }
        }
      },
      "children": []
    },
    "asset_allocation_button": {
      "type": "Button",
      "props": {
        "label": "Asset Allocation",
        "variant": "borderless"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.bogleheads.org/wiki/Asset_allocation"
          }
        }
      },
      "children": []
    }
  }
}
